CREATE TABLE "ExecutiveDecisionLog" ("id" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"actorId" TEXT,"source" TEXT NOT NULL,"entityType" TEXT,"entityId" TEXT,"recommendation" TEXT NOT NULL,"reason" TEXT,"confidence" DOUBLE PRECISION,"decision" TEXT,"decisionNote" TEXT,"decidedAt" TIMESTAMP(3),"outcome" TEXT,"outcomeScore" DOUBLE PRECISION,"outcomeNote" TEXT,"evaluatedAt" TIMESTAMP(3),"context" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ExecutiveDecisionLog_pkey" PRIMARY KEY ("id"));CREATE INDEX "ExecutiveDecisionLog_agencyId_createdAt_idx" ON "ExecutiveDecisionLog"("agencyId","createdAt");CREATE INDEX "ExecutiveDecisionLog_entityType_entityId_idx" ON "ExecutiveDecisionLog"("entityType","entityId");